// Rendering only: Blender-authored prototypes, procedural joints and 1.5s breakup.
import * as THREE from '../assets/three.module.js';
const colorFor=team=>team==='Light'?'#75d7ff':team==='Dark'?'#ff6f87':'#c790fa';
export class CombatView{
 constructor({world,state,actors,palette,camera,labels}){Object.assign(this,{world,state,actors,palette,camera,labels});this.miniDots=new Map();this.templates=new Map();this.units=new Map();this.bars=new Map();this.staticRoots=new Map();this.v=new THREE.Vector3();this.shardGeometry=new THREE.TetrahedronGeometry(.17);this.auraGeometry=new THREE.RingGeometry(1.12,1.2,40);this.auraMaterial=new THREE.MeshBasicMaterial({color:'#ffdc7a',side:THREE.DoubleSide,transparent:true,opacity:.75,depthWrite:false});
  for(const a of actors.values()){if(a.motion==='minion_template'){a.go.visible=false;this.templates.set(a.template_key,a.go);}if(a.motion==='neutral'||a.motion==='structure')this.staticRoots.set(a.owner,a);}
 }
 create(u){const template=this.templates.get(u.team+'_'+u.kind);if(!template)throw new Error('Missing Blender minion template '+u.team+'_'+u.kind);const go=new THREE.Group(),body=template.clone(true);body.visible=true;body.position.set(0,0,0);body.quaternion.identity();body.scale.set(1,1,1);go.add(body);go.userData.runtimeID=u.id;const parts=[];body.traverse(o=>{if(o.userData.part){o.userData.rest={p:o.position.clone(),q:o.quaternion.clone(),s:o.scale.clone()};parts.push(o);}});const aura=new THREE.Mesh(this.auraGeometry,this.auraMaterial);aura.rotation.x=-Math.PI/2;aura.position.y=.36;aura.visible=u.blessed;go.add(aura);this.world.add(go);const item={go,body,parts,aura,unit:u,shards:[],materials:[],dead:false};this.units.set(u.id,item);return item;}
 shards(item,team){if(item.shards.length)return;for(let i=0;i<8;i++){const mesh=new THREE.Mesh(this.shardGeometry,new THREE.MeshBasicMaterial({color:i%3?'#e8cf8d':colorFor(team),transparent:true}));mesh.userData.angle=i*2.39996;item.go.add(mesh);item.shards.push(mesh);}}
 death(item,u,age){if(!item.dead){item.dead=true;item.restBody=item.body.position.clone();item.body.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.material.transparent=true;o.material.depthWrite=false;item.materials.push(o.material);}});this.shards(item,u.team);}const f=Math.min(1,age/1.5);item.body.position.y=item.restBody.y-f*.9;item.body.rotation.z=f*.28;item.body.scale.setScalar(Math.max(.001,1-f*.7));for(const m of item.materials)m.opacity=Math.max(0,1-f);for(let i=0;i<item.shards.length;i++){const s=item.shards[i],a=s.userData.angle;s.position.set(Math.cos(a)*f*2.2,.9+Math.sin(f*Math.PI)*1.3-f*.8,Math.sin(a)*f*2.2);s.rotation.set(f*4+i,f*7,0);s.material.opacity=1-f;s.scale.setScalar(1-f*.7);}item.go.visible=age<1.5;}
 bar(u,height){let bar=this.bars.get(u.id);if(!bar){const el=document.createElement('span'),fill=document.createElement('i');el.className='combat-health '+(u.team==='Light'?'light':u.team==='Dark'?'dark':'neutral');el.append(fill);this.labels.append(el);bar={el,fill};this.bars.set(u.id,bar);}this.v.set(u.position.x,height,u.position.z).project(this.camera);bar.el.style.visibility=u.alive&&this.camera.zoom>2.5&&this.v.z>-1&&this.v.z<1&&Math.abs(this.v.x)<1.05&&Math.abs(this.v.y)<1.05?'visible':'hidden';bar.el.style.left=`${(this.v.x*.5+.5)*innerWidth}px`;bar.el.style.top=`${(-this.v.y*.5+.5)*innerHeight}px`;bar.fill.style.width=`${u.health/u.maxHealth*100}%`;}
 mini(u){const root=document.getElementById('mini-map');if(!root)return;let dot=this.miniDots.get(u.id);if(!dot){dot=document.createElementNS('http://www.w3.org/2000/svg','circle');dot.setAttribute('r',u.category==='minion'?'1.2':u.category==='boss'?'3.2':'1.7');dot.setAttribute('fill',colorFor(u.team));root.append(dot);this.miniDots.set(u.id,dot);}dot.setAttribute('cx',u.position.x);dot.setAttribute('cy',u.position.z);dot.setAttribute('visibility',u.alive?'visible':'hidden');}
 frame(time){const s=this.state;
  for(const u of s.minions.values()){let item=this.units.get(u.id)??this.create(u);item.unit=u;this.mini(u);const {go,body,parts}=item;go.position.set(u.position.x,0,u.position.z);go.rotation.y=u.heading;body.position.y=s.renderHeight(u.position);if(!u.alive){this.death(item,u,time-u.deadAt);this.bars.get(u.id)?.el.style.setProperty('visibility','hidden');continue;}const attack=Math.max(0,1-(time-u.attackAt)/.42),swing=Math.sin(attack*Math.PI),walk=u.state==='MoveAlongLane'?Math.sin(time*9+u.id):0;
   if(u.kind==='Caster')body.position.y+=.25+Math.sin(time*2.6+u.id)*.12;else body.rotation.z=u.kind==='Guard'?walk*.035:0;
   for(const part of parts){const rest=part.userData.rest;part.position.copy(rest.p);part.quaternion.copy(rest.q);switch(part.userData.part){case 'leg_left':part.rotation.x+=walk*.48;break;case 'leg_right':part.rotation.x-=walk*.48;break;case 'shield':part.rotation.y+=walk*.08;part.position.z+=swing*.14;break;case 'blade':part.rotation.x+=swing*1.6;part.position.z+=swing*.22;part.rotation.z+=swing*.25;break;case 'staff':part.rotation.x-=swing*.9;part.position.y+=swing*.25;break;case 'wheel':part.rotation.x-=u.travel/.54;break;case 'cannon':part.position.z-=swing*.40;part.position.y+=Math.sin(time*18)*.014;break;}}
   item.aura.visible=u.blessed;item.aura.rotation.z=time*.35;this.bar(u,s.renderHeight(u.position)+3.2);
  }
  for(const [id,item]of this.units)if(!s.minions.has(id)){this.world.remove(item.go);for(const m of item.materials)m.dispose();for(const shard of item.shards)shard.material.dispose();this.units.delete(id);this.bars.get(id)?.el.remove();this.bars.delete(id);this.miniDots.get(id)?.remove();this.miniDots.delete(id);}
  for(const [id,a]of this.staticRoots){const u=s.neutrals.get(id)??s.structures.get(id),go=a.go;if(!u)continue;this.mini(u);const age=u.deadAt===null?Infinity:time-u.deadAt;go.visible=u.alive||age<1.5;if(u.alive){go.position.copy(a.base.p);go.quaternion.copy(a.base.q);go.scale.copy(a.base.s);if(s.neutrals.has(id)){go.position.x=u.position.x;go.position.z=u.position.z;const floating=['Watcher','RiftRay','RiftWraith'].includes(u.kind);if(floating)go.position.y+=Math.sin(time*2+id)*.14;const attack=Math.max(0,1-(time-u.attackAt)/.4);go.rotation.x+=Math.sin(attack*Math.PI)*.10;}else{const pulse=Math.max(0,1-(time-u.attackAt)/.24);go.scale.multiplyScalar(1+Math.sin(pulse*Math.PI)*.018);}}
   else if(age<1.5){go.scale.copy(a.base.s).multiplyScalar(Math.max(.001,1-age/1.5));go.position.y=a.base.p.y-age*.65;go.rotation.z=age*.12;}
   if(u.alive)this.bar(u,(a.motion==='structure'?8:a.base.p.y+(u.category==='boss'?10:4)));else this.bars.get(id)?.el.style.setProperty('visibility','hidden');
  }
 }
 pick(ray){const hits=ray.intersectObjects([...this.units.values()].filter(i=>i.unit.alive).map(i=>i.go),true);return hits.length?this.owner(hits[0].object):null;}
 owner(go){while(go&&!go.userData.runtimeID)go=go.parent;return go?.userData.runtimeID??null;}
 reset(){for(const [id,item]of this.units){this.world.remove(item.go);for(const m of item.materials)m.dispose();for(const shard of item.shards)shard.material.dispose();this.bars.get(id)?.el.remove();this.bars.delete(id);this.miniDots.get(id)?.remove();this.miniDots.delete(id);}this.units.clear();}
}
